{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "od-plugin-authoring",
  "title": "Plugin authoring",
  "title_i18n": {
    "en": "Plugin authoring",
    "zh-CN": "插件编写",
    "zh-TW": "外掛編寫",
    "ja": "プラグイン作成",
    "ko": "플러그인 작성",
    "de": "Plugin-Erstellung",
    "fr": "Création de plugin",
    "ru": "Создание плагина",
    "es": "Creación de plugin",
    "pt-BR": "Criação de plugin",
    "it": "Creazione plugin",
    "vi": "Tạo plugin",
    "pl": "Tworzenie wtyczki",
    "id": "Pembuatan plugin",
    "nl": "Plug-in maken",
    "ar": "تأليف الإضافة",
    "tr": "Eklenti yazma",
    "uk": "Створення плагіна"
  },
  "version": "0.1.0",
  "publishedAt": "2026-05-12T13:38:45Z",
  "description": "Guided scenario for creating a local Open Design plugin folder that can be added to My plugins.",
  "description_i18n": {
    "en": "Guided scenario for creating a local Open Design plugin folder that can be added to My plugins.",
    "zh-CN": "引导式场景：创建一个本地 Open Design 插件文件夹，可加到「我的插件」。",
    "zh-TW": "引導式場景：建立一個本地 Open Design 外掛資料夾，可加到「我的外掛」。",
    "ja": "My plugins に追加できる、ローカル Open Design プラグインフォルダを作成するためのガイド付きシナリオ。",
    "ko": "My plugins에 추가할 수 있는 로컬 Open Design 플러그인 폴더를 만드는 가이드 시나리오.",
    "de": "Geführtes Szenario zum Anlegen eines lokalen Open-Design-Plugin-Ordners, den du zu My plugins hinzufügen kannst.",
    "fr": "Scénario guidé pour créer un dossier de plugin Open Design local à ajouter dans My plugins.",
    "ru": "Сценарий-гид для создания локальной папки Open Design плагина, которую можно добавить в My plugins.",
    "es": "Escenario guiado para crear una carpeta de plugin de Open Design local que puedes añadir a My plugins.",
    "pt-BR": "Cenário guiado para criar uma pasta de plugin Open Design local que pode ser adicionada a My plugins.",
    "it": "Scenario guidato per creare una cartella di plugin Open Design locale da aggiungere a My plugins.",
    "vi": "Kịch bản hướng dẫn tạo thư mục plugin Open Design cục bộ để thêm vào My plugins.",
    "pl": "Kreator scenariusz tworzenia lokalnego folderu wtyczki Open Design, który można dodać do My plugins.",
    "id": "Skenario terpandu untuk membuat folder plugin Open Design lokal yang bisa ditambahkan ke My plugins.",
    "nl": "Begeleid scenario voor het maken van een lokale Open Design-plug-inmap die je aan My plugins kunt toevoegen.",
    "ar": "سيناريو موجَّه لإنشاء مجلد إضافة Open Design محلي يمكن إضافته إلى My plugins.",
    "tr": "My plugins'e eklenebilen yerel bir Open Design eklenti klasörü oluşturmak için rehberli senaryo.",
    "uk": "Покроковий сценарій створення локальної теки плагіна Open Design, яку можна додати до My plugins."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/scenarios/od-plugin-authoring",
  "tags": [
    "scenario",
    "first-party",
    "plugin-authoring",
    "my-plugins"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "scenario": "plugin-authoring",
    "mode": "scenario",
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "plan",
          "atoms": [
            "direction-picker",
            "todo-write"
          ]
        },
        {
          "id": "generate-plugin",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        },
        {
          "id": "review-plugin",
          "atoms": [
            "critique-theater"
          ],
          "repeat": true,
          "until": "critique.score>=4 || iterations>=3"
        }
      ]
    },
    "capabilities": [
      "prompt:inject"
    ],
    "useCase": {
      "query": {
        "en": "Create an Open Design plugin for {{pluginGoal}}. Produce a folder named generated-plugin with SKILL.md, open-design.json, and any useful examples or assets. Follow docs/plugins-spec.md and finish with a readiness summary plus next actions: Add to My plugins, Publish repo, or Open Design PR.",
        "zh-CN": "为 {{pluginGoal}} 创建一个 Open Design 插件。请生成名为 generated-plugin 的文件夹，包含 SKILL.md、open-design.json，以及有用的 examples 或 assets。遵循 docs/plugins-spec.md，并在最后总结它是否可以添加到 My plugins，同时给出下一步操作：添加到 My plugins、发布仓库或创建 Open Design PR。"
      },
      "exampleOutputs": [
        {
          "path": "./examples/generated-plugin/open-design.json",
          "title": "Generated plugin manifest"
        }
      ]
    },
    "inputs": [
      {
        "name": "pluginGoal",
        "type": "string",
        "required": false,
        "default": "a reusable workflow described by the user's prompt",
        "label": "Plugin goal",
        "placeholder": "turn a brand brief into a launch landing page workflow"
      }
    ]
  }
}
